  const lineOf = (needle) => Math.max(1, lines.findIndex((l) => l.includes(needle)) + 1)
  const names = new Set(reg.items.map((i) => i.name))
  for (const item of reg.items) {
    const at = lineOf(`"name": "${item.name}"`)
    const d = item.description ?? ""
    const words = d.trim().split(/\s+/).filter(Boolean).length
    if (!d) report("copy-description", file, at, `${item.name}: no description.`)
    else if (words > 12) report("copy-description", file, at, `${item.name}: description is ${words} words (max 12).`)
    else if ((d.match(/[.!?](\s|$)/g) ?? []).length > 1) report("copy-description", file, at, `${item.name}: description is more than one sentence.`)
    if (d) {
      checkCopy(d, file, at, "registry description")
      checkNames(`${item.title ?? ""} ${d}`, file, at)
      if (/\d+\s?(px|rem|ms)\b|\.(tsx?|css|json)\b|\//.test(d)) report("copy-description", file, at, `${item.name}: values and paths belong on the detail page, not in the description.`)
    }
    for (const f of item.files ?? []) {
      const base = path.basename(f.path).replace(/\.\w+$/, "")
      if (/\/parts\//.test(f.path) && base !== item.name && names.has(base))
        report("registry-name-collision", file, lineOf(f.path), `${item.name}: part "${path.basename(f.path)}" has the same name as the "${base}" item; rename it so imports and installs can't collide.`)
    }
  }
}

/* ────────────────────────────── theme upgrade ────────────────────────────── */

function themeFile() {
  if (config.theme) return path.join(cwd, config.theme)
  const cfg = readJson(path.join(cwd, "components.json"))
  const cand = [cfg?.tailwind?.css, "app/globals.css", "src/app/globals.css", "styles/globals.css", "src/styles/globals.css"].filter(Boolean)
  return cand.map((p) => path.join(cwd, p)).find((p) => fs.existsSync(p))
}

function checkUpgrade() {
  if (!on("upgrade")) return
  const script = ["scripts/qinyang-upgrade-check.mjs", "registry/base-nova/scripts/upgrade-check.mjs"].map((p) => path.join(cwd, p)).find((p) => fs.existsSync(p))
  if (script) {
    const r = spawnSync(process.execPath, [script], { cwd, encoding: "utf8" })
    const out = `${r.stdout ?? ""}${r.stderr ?? ""}`.trim()
    if (r.status !== 0) report("upgrade", script, 1, `the upgrade check found something to fix:\n${out.replace(/^/gm, "      ")}`)
    return
  }
  const css = themeFile()
  if (!css) return
  const text = fs.readFileSync(css, "utf8")
  if (!/--radius:/.test(text)) return // not a qinyang/ui theme
  if (/--(?:color-)?accent-(?:50|[1-9]00|950):/.test(text)) report("upgrade", css, 1, "The removed accent ramp (--accent-50…950) is still in the stylesheet; install the upgrade-check item and run it with --fix.")
  if (!/--radius-max:/.test(text)) report("upgrade", css, 1, "No --radius-max: the theme predates the 16px cap; reinstall the theme.")
  const r = text.match(/--radius:\s*([\d.]+)rem/)
  if (r && parseFloat(r[1]) > 1) report("upgrade", css, 1, `--radius ${r[1]}rem is above the supported 1rem.`)
}

/* ────────────────────────────── run ────────────────────────────── */

const SELF = path.resolve(new URL(import.meta.url).pathname)

// Rules that read JSX structure, so they only run with the TypeScript parser.
const JSX_RULES = new Set(["concentric-radius", "menu-label-group", "tabular-nums", "text-wrap", "media-outline", "hit-area", "presence-initial", "exit-subtle", "icon-swap", "icon-stroke", "icon-size", "icon-color", "icon-rtl", "optical-icon-padding", "icon-button-label"])

// --self-test: every examples/<rule>/bad.tsx must trip <rule>; every good.tsx must be clean.
if (flag("--self-test")) {
  const dir = path.join(path.dirname(path.dirname(SELF)), "examples")
  PRESS_SCALE_OK.add("good").add("bad")
  config.rtl = true
  themeSmooths = false
  let failed = 0, cases = 0
  for (const rule of fs.readdirSync(dir).sort()) {
    if (!RULES[rule]) {
      console.log(`  ?  examples/${rule}: no rule with this id`)
      failed++
      continue
    }
    if (!ts && JSX_RULES.has(rule)) {
      console.log(`  --  ${rule}: needs TypeScript to read JSX, skipped`)
      continue
    }
    for (const kind of ["bad", "good"]) {
      const file = path.join(dir, rule, `${kind}.tsx`)
      if (!fs.existsSync(file)) continue
      cases++
      findings.length = 0
      seenFindings.clear()
      const text = fs.readFileSync(file, "utf8")
      fileLines.set(file, text.split("\n"))
      checkSourceText(file, text)
      if (ts) checkSourceTs(file, text)
      else checkSourcePlain(file, text)
      const hit = findings.filter((f) => f.rule === rule)
      const ok = kind === "bad" ? hit.length > 0 : findings.length === 0
      if (!ok) failed++
      console.log(`  ${ok ? "ok" : "FAIL"}  ${rule}/${kind}${ok ? "" : `: ${kind === "bad" ? "not reported" : findings.map((f) => `${f.rule} (line ${f.line})`).join(", ")}`}`)
    }
  }
  console.log(`\n${cases} examples, ${failed} failed${ts ? "" : ` (${tsNote}: JSX checks skipped)`}`)
  process.exit(failed ? 1 : 0)
}
const SKILL_DIR = path.dirname(path.dirname(SELF)) + path.sep
let tsFailures = 0
for (const file of files) {
  if (path.resolve(file) === SELF) continue
  // Installed copies of this skill are reference text, not project code.
  if (path.resolve(file).startsWith(SKILL_DIR) && !/\.md$/.test(file)) continue
  if (/[\\/]skills[\\/]qinyang-design[\\/]/.test(file) && !path.resolve(file).startsWith(SKILL_DIR)) continue
  const text = fs.readFileSync(file, "utf8")
  if (/^\s*(\/\/|\/\*|#)\s*GENERATED\b/.test(text.slice(0, 200))) continue
  fileLines.set(file, text.split("\n"))
  if (/\.(tsx|jsx|ts|js|mjs|cjs)$/.test(file)) checkSourceText(file, text)
  if (file.endsWith("registry.json")) checkRegistry(file, text)
  else if (/\.css$/.test(file)) checkCss(file, text)
  else if (/\.mdx?$/.test(file)) checkMarkdown(file, text)
  else if (ts) {
    // A compiler that loads but fails on a file falls back to the regex checks for that file.
    const before = findings.length
    try {
      checkSourceTs(file, text)
    } catch {
      for (const f of findings.splice(before)) seenFindings.delete(`${f.rule}\u0000${f.file}\u0000${f.line}\u0000${f.message}`)
      tsFailures++
      checkSourcePlain(file, text)
    }
  } else checkSourcePlain(file, text)
}
checkUpgrade()

const shown = flag("--quiet") ? findings.filter((f) => f.level === "error") : findings
const errors = findings.filter((f) => f.level === "error").length
const warns = findings.length - errors

if (flag("--json")) console.log(JSON.stringify({ files: files.length, errors, warnings: warns, findings: shown }, null, 2))
else {
  let last = ""
  for (const f of shown.sort((a, b) => a.file.localeCompare(b.file) || a.line - b.line)) {
    if (f.file !== last) console.log(`\n${f.file}`)
    last = f.file
    console.log(`  ${String(f.line).padStart(4)}  ${f.level === "error" ? "error" : "warn "}  ${f.rule.padEnd(24)} ${f.message}`)
  }
  console.log(`\n${files.length} files, ${errors} errors, ${warns} warnings${ts ? (tsFailures ? ` (${tsFailures} files read without TypeScript)` : "") : ` (${tsNote}: JSX nesting checks skipped)`}`)
}
process.exit(errors || (flag("--strict") && warns) ? 1 : 0)

/**
 * Polish probe for any page: paste into the browser console (or run with Playwright's
 * page.evaluate) after opening the screen you want to check. It reads what the static check
 * can't see, from computed styles and layout:
 *
 *   hit-area          interactive targets under 24px (44px under a coarse pointer), counting
 *                     an absolutely positioned ::before / ::after as part of the target, that
 *                     have another target within that distance
 *   hit-overlap       two targets whose extended areas overlap while their boxes don't
 *   optical-padding   a button with an icon on one side and equal padding on both sides
 *   media-outline     images and video of 24px or more with no outline
 *   text-wrap         a heading that wraps onto more lines without text-wrap: balance / pretty
 *   tabular-nums      live numbers (role timer, status, progressbar, aria-live, <output>) in
 *                     proportional digits
 *   font-smoothing    body text not antialiased (only matters on macOS)
 *   transition-all    an element that transitions every property
 *   will-change       a hint on a property that can't be composited
 *
 * Returns the findings and prints them as a table. Inline text links and hidden elements are
 * skipped. The library's own audit runs the same function.
 */
;(() => {
  function polish({ coarse = matchMedia("(pointer: coarse)").matches } = {}) {
    const MIN = coarse ? 44 : 24
    const out = []
    const sel = (el) => {
      const slot = el.getAttribute("data-slot")
      const id = el.id ? `#${el.id}` : ""
      const label = el.getAttribute("aria-label")
      return `${el.tagName.toLowerCase()}${id}${slot ? `[data-slot=${slot}]` : ""}${label ? `[aria-label="${label.slice(0, 30)}"]` : ""}`
    }
    const shown = (el, r) => {
      if (r.width < 1 || r.height < 1) return false
      const cs = getComputedStyle(el)
      return cs.visibility !== "hidden" && cs.display !== "none" && parseFloat(cs.opacity) > 0.01
    }
    const add = (rule, el, detail) => out.push({ rule, element: sel(el), detail })

    /* Hit areas */
    const TARGETS =
      'button, a[href], input:not([type=hidden]), select, textarea, summary, [role=button], [role=checkbox], [role=radio], [role=switch], [role=tab], [role=menuitem], [role=option], [role=slider], [tabindex="0"]'
    const boxes = []
    for (const el of document.querySelectorAll(TARGETS)) {
      const r = el.getBoundingClientRect()
      if (!shown(el, r)) continue
      if (el.closest("[inert], [aria-hidden=true]")) continue
      const cs = getComputedStyle(el)
      // Inline links inside running text are exempt (their line sets the target).
      if (el.tagName === "A" && cs.display === "inline" && el.parentElement && /\S/.test(el.parentElement.textContent.replace(el.textContent, ""))) continue
      // A control wrapped in a label takes the label's box as its target.
      const label = el.closest("label")
      let hit = { l: r.left, t: r.top, r: r.right, b: r.bottom }
      if (label && label !== el) {
        const lr = label.getBoundingClientRect()
        hit = { l: Math.min(hit.l, lr.left), t: Math.min(hit.t, lr.top), r: Math.max(hit.r, lr.right), b: Math.max(hit.b, lr.bottom) }
      }
      for (const pseudo of ["::before", "::after"]) {
        const ps = getComputedStyle(el, pseudo)
        if (ps.content === "none" || ps.display === "none" || !/absolute|fixed/.test(ps.position)) continue
        const v = (k) => (ps[k] === "auto" ? null : parseFloat(ps[k]))
        const [top, right, bottom, left] = ["top", "right", "bottom", "left"].map(v)
        const w = parseFloat(ps.width), h = parseFloat(ps.height)
        // Resolved against the element itself (the usual `relative` host).
        // Centred with a transform (top/left 50% plus a translate): sized by width and height.
        if (ps.transform !== "none" && w > 0 && h > 0) {
          hit = { l: Math.min(hit.l, r.left + (r.width - w) / 2), t: Math.min(hit.t, r.top + (r.height - h) / 2), r: Math.max(hit.r, r.left + (r.width + w) / 2), b: Math.max(hit.b, r.top + (r.height + h) / 2) }
          continue
        }
        const pl = left != null ? r.left + left : right != null ? r.right - right - w : r.left + (r.width - w) / 2
        const pt = top != null ? r.top + top : bottom != null ? r.bottom - bottom - h : r.top + (r.height - h) / 2
        const pr = right != null ? r.right - right : pl + w
        const pb = bottom != null ? r.bottom - bottom : pt + h
        hit = { l: Math.min(hit.l, pl), t: Math.min(hit.t, pt), r: Math.max(hit.r, pr), b: Math.max(hit.b, pb) }
      }
      boxes.push({ el, r, hit, small: Math.min(hit.r - hit.l, hit.b - hit.t) + 0.5 < MIN })
    }
    // An undersized target passes when a MIN-sized square centred on it reaches no other target
    // (the spacing exception), so a lone 20px switch is fine and a row of 6px dots is not.
    for (const a of boxes) {
      if (!a.small) continue
      const cx = (a.hit.l + a.hit.r) / 2, cy = (a.hit.t + a.hit.b) / 2, h = MIN / 2
      const zone = { l: Math.min(a.hit.l, cx - h), t: Math.min(a.hit.t, cy - h), r: Math.max(a.hit.r, cx + h), b: Math.max(a.hit.b, cy + h) }
      const near = boxes.find((b) => b !== a && !a.el.contains(b.el) && !b.el.contains(a.el) && b.hit.l < zone.r - 0.5 && b.hit.r > zone.l + 0.5 && b.hit.t < zone.b - 0.5 && b.hit.b > zone.t + 0.5)
      if (near) add("hit-area", a.el, `${Math.round(a.hit.r - a.hit.l)}×${Math.round(a.hit.b - a.hit.t)}px target, under ${MIN}px and within ${MIN}px of ${sel(near.el)}`)
    }
    // Overlapping extended targets (sorted sweep on x).
    boxes.sort((a, b) => a.hit.l - b.hit.l)
    for (let i = 0; i < boxes.length; i++) {
      const a = boxes[i]
      for (let j = i + 1; j < boxes.length && boxes[j].hit.l < a.hit.r; j++) {
        const b = boxes[j]
        if (a.el.contains(b.el) || b.el.contains(a.el)) continue
        const ix = Math.min(a.hit.r, b.hit.r) - Math.max(a.hit.l, b.hit.l)
        const iy = Math.min(a.hit.b, b.hit.b) - Math.max(a.hit.t, b.hit.t)
        if (ix <= 1 || iy <= 1) continue
        const vx = Math.min(a.r.right, b.r.right) - Math.max(a.r.left, b.r.left)
        const vy = Math.min(a.r.bottom, b.r.bottom) - Math.max(a.r.top, b.r.top)
        if (vx > 0 && vy > 0) continue // the boxes themselves overlap: a layout choice, not a hit-area one
        add("hit-overlap", a.el, `extended target overlaps ${sel(b.el)} by ${Math.round(ix)}×${Math.round(iy)}px`)
      }
    }

    /* Buttons with an icon on one side */
    for (const el of document.querySelectorAll("button, a[data-slot=button], [role=button]")) {
      const r = el.getBoundingClientRect()
      if (!shown(el, r) || !el.textContent.trim()) continue
      const kids = [...el.children].filter((k) => getComputedStyle(k).position !== "absolute")
      if (kids.length < 1) continue
      const firstIcon = kids[0]?.tagName === "svg"
      const lastIcon = kids[kids.length - 1]?.tagName === "svg"
      if (firstIcon === lastIcon) continue
      const cs = getComputedStyle(el)
      if (/inset/.test(cs.boxShadow)) continue // a field-styled trigger keeps the input's padding
      const ps = parseFloat(cs.paddingInlineStart), pe = parseFloat(cs.paddingInlineEnd)
      if (ps >= 6 && Math.abs(ps - pe) < 0.5) add("optical-padding", el, `icon on the ${firstIcon ? "start" : "end"} side with ${ps}px padding on both sides; trim 2px on the icon side`)
    }

    /* Media */
    for (const el of document.querySelectorAll("img, video, picture > img")) {
      const r = el.getBoundingClientRect()
      if (!shown(el, r) || Math.min(r.width, r.height) < 24 || el.getAttribute("aria-hidden") === "true") continue
      const cs = getComputedStyle(el)
      if (cs.outlineStyle === "none" || parseFloat(cs.outlineWidth) === 0) add("media-outline", el, "no outline; add media-outline")
    }

    /* Headings */
    for (const el of document.querySelectorAll("h1, h2, h3")) {
      const r = el.getBoundingClientRect()
      if (!shown(el, r)) continue
      const cs = getComputedStyle(el)
      const lh = parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.2
      const wrap = cs.textWrapStyle || cs.textWrap || ""
      if (r.height > lh * 1.5 && !/balance|pretty/.test(wrap) && cs.whiteSpace !== "nowrap") add("text-wrap", el, `wraps to ${Math.round(r.height / lh)} lines without text-wrap: balance`)
    }

    /* Live numbers */
    for (const el of document.querySelectorAll('[role=timer], [role=status], [role=progressbar], [aria-live]:not([aria-live=off]), output, [data-live-number]')) {
      if (!/\d/.test(el.textContent)) continue
      const r = el.getBoundingClientRect()
      if (!shown(el, r)) continue
      const cs = getComputedStyle(el)
      if (!/tabular-nums/.test(cs.fontVariantNumeric) && !/mono/i.test(cs.fontFamily)) add("tabular-nums", el, `live number in proportional digits ("${el.textContent.trim().slice(0, 24)}")`)
    }

    /* Root text */
    const body = getComputedStyle(document.body)
    if (body.webkitFontSmoothing && body.webkitFontSmoothing !== "antialiased") add("font-smoothing", document.body, `-webkit-font-smoothing is ${body.webkitFontSmoothing}`)

    /* Transitions and compositing hints */
    const OK = /^(auto|transform|opacity|filter|translate|scale|rotate|backdrop-filter|scroll-position)$/
    for (const el of document.querySelectorAll("body *")) {
      const cs = getComputedStyle(el)
      if (cs.transitionProperty.split(",").some((p) => p.trim() === "all") && cs.transitionDuration.split(",").some((d) => parseFloat(d) > 0))
        add("transition-all", el, `transition-property: all (${cs.transitionDuration})`)
      if (cs.willChange !== "auto") {
        const bad = cs.willChange.split(",").map((p) => p.trim()).filter((p) => !OK.test(p))
        if (bad.length) add("will-change", el, `will-change: ${cs.willChange}`)
      }
    }
    return out
  }

  const found = polish()
  console.table(found)
  return found
})()

/**
 * Nested-radius probe for any page: paste into the browser console (or run with
 * Playwright's page.evaluate) after opening the screen you want to check, with
 * menus open or rows hovered if those are what you are checking.
 *
 * For every rounded element it compares the corner radius with the concentric
 * value its nearest rounded ancestor implies (outer radius minus the inset) and
 * prints the ones more than 2px off. "must" = inset of 8px or less, fix it with
 * frame-* on the container and rounded-inner on the child.
 *
 * The measuring function is the same one the library's own audit runs.
 */
(() => {
  function measure({ tol, maxInset, phase }) {
    const px = (v, w) => {
      const first = String(v).trim().split(/\s+/)[0]
      if (first.endsWith("%")) return (parseFloat(first) / 100) * w
      return parseFloat(first) || 0
    }
    const alpha = (c) => {
      if (!c || c === "transparent") return 0
      const m = c.match(/rgba?\(([^)]+)\)/)
      if (m) {
        const parts = m[1].split(/[ ,/]+/).filter(Boolean)
        return parts.length > 3 ? parseFloat(parts[3]) : 1
      }
      const a = c.match(/\/\s*([\d.]+%?)\s*\)/)
      if (a) return a[1].endsWith("%") ? parseFloat(a[1]) / 100 : parseFloat(a[1])
      return 1
    }
    // Does the box paint anything at this corner (or anywhere, when corner is omitted)?
    const SIDES = { tl: ["Top", "Left"], tr: ["Top", "Right"], br: ["Bottom", "Right"], bl: ["Bottom", "Left"] }
    const painted = (el, cs, corner) => {
      if (/^(IMG|VIDEO|CANVAS|IFRAME|PICTURE)$/.test(el.tagName)) return true
      const textClip = /text/.test(cs.backgroundClip || cs.webkitBackgroundClip || "")
      if (!textClip && (alpha(cs.backgroundColor) > 0.01 || cs.backgroundImage !== "none")) return true
      if (cs.boxShadow && cs.boxShadow !== "none") return true
      for (const s of corner ? SIDES[corner] : ["Top", "Right", "Bottom", "Left"]) {
        if (parseFloat(cs[`border${s}Width`]) > 0 && cs[`border${s}Style`] !== "none" && alpha(cs[`border${s}Color`]) > 0.01) return true
      }
      if (cs.backdropFilter && cs.backdropFilter !== "none") return true
      return false
    }
    // A scroll container between the element and its ancestor (or the ancestor itself) moves
    // the element, so its offsets depend on the scroll position.
    const scrolls = (n) => {
      const c = getComputedStyle(n)
      return /(auto|scroll)/.test(c.overflowY + c.overflowX) && (n.scrollHeight > n.clientHeight + 1 || n.scrollWidth > n.clientWidth + 1)
    }
    const radii = (el, cs, r) => {
      const w = r.width, h = r.height, cap = Math.min(w, h) / 2
      const c = (v) => Math.min(px(v, w), cap)
      return {
        tl: c(cs.borderTopLeftRadius),
        tr: c(cs.borderTopRightRadius),
        br: c(cs.borderBottomRightRadius),
        bl: c(cs.borderBottomLeftRadius),
        cap,
      }
    }
    const isRound = (rr) => rr.cap > 0 && Math.max(rr.tl, rr.tr, rr.br, rr.bl) >= rr.cap - 1 && Math.min(rr.tl, rr.tr, rr.br, rr.bl) >= rr.cap - 1
    const RADIUS_CLASS = /^(?:[a-z0-9-]+:)*(rounded|frame|p|px|py|pt|pb|pl|pr|ps|pe|border|inset|gap|m|mx|my|shell-inset)(-|$)/
    const radiusClasses = (el) =>
      String(el.getAttribute("class") || "")
        .split(/\s+/)
        .filter((c) => RADIUS_CLASS.test(c))
        .join(" ")
    const short = (el) => {
      let s = el.tagName.toLowerCase()
      const slot = el.getAttribute("data-slot")
      if (slot) return `${s}[data-slot="${slot}"]`
      if (el.id) return `${s}#${el.id}`
      const role = el.getAttribute("role")
      if (role) s += `[role="${role}"]`
      const cls = String(el.getAttribute("class") || "").split(/\s+/).filter((c) => c && !c.includes(":") && !c.includes("[") && !c.includes("/"))
      if (cls.length) s += "." + cls.slice(0, 2).join(".")
